'use strict';
// Standalone synthetic prototype. No API, auth token, storage provider or database calls.
const main=document.querySelector('#main'),dialog=document.querySelector('#dialog');
const students=[
 {code:'102230101',name:'Nguyễn Minh Anh',className:'23T_Nhat1',policy:'M2 · Sinh viên khuyết tật',rate:'100%',period:'01/09/2026 – 31/01/2027',candidates:[['M2 · Sinh viên khuyết tật','100%','01/09/2026 – 31/01/2027',true],['M9 · Con cán bộ đã nghỉ hưu','25%','01/09/2026 – 31/01/2027',false]]},
 {code:'102230218',name:'Trần Hải Yến',className:'23KTHH1',policy:'M8 · Con cán bộ đang công tác',rate:'50%',period:'01/09/2026 – 31/10/2026',candidates:[['M8 · Con cán bộ đang công tác','50%','01/09/2026 – 31/10/2026',true],['M9 · Con cán bộ đã nghỉ hưu','25%','01/09/2026 – 31/01/2027',false]]},
 {code:'102230306',name:'Lê Quốc Bảo',className:'23DT1',policy:'M2 · Sinh viên khuyết tật',rate:'100%',period:'01/09/2026 – 31/01/2027',candidates:[['M2 · Sinh viên khuyết tật','100%','01/09/2026 – 31/01/2027',true]]}
];
let state={created:false,versions:[],selected:0,tab:'list',screen:'list',round:'ready'};
const time=s=>new Intl.DateTimeFormat('vi-VN',{dateStyle:'short',timeStyle:'short',timeZone:'Asia/Ho_Chi_Minh'}).format(new Date(s));
const escape=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function toast(text,error=false){const t=document.createElement('div');t.className='toast'+(error?' error':'');t.setAttribute('role',error?'alert':'status');t.innerHTML='<button aria-label="Đóng thông báo">×</button><strong>'+(error?'Chưa thể hoàn tất thao tác':'Đã hoàn tất')+'</strong><div>'+escape(text)+'</div>';document.querySelector('#feedback').replaceChildren(t);t.querySelector('button').onclick=()=>t.remove();if(!error)setTimeout(()=>t.remove(),6000);}
function modal(html){dialog.innerHTML=html;dialog.showModal();dialog.querySelectorAll('[data-close]').forEach(b=>b.onclick=()=>dialog.close());}
dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)dialog.close();}});
function render(){state.screen==='list'?list():detail();}
function list(){
 main.innerHTML='<div class="page-head"><div><div class="eyebrow">Miễn giảm học phí / Hội đồng & quyết định</div><h1>Hội đồng và quyết định</h1><p class="muted">Chuẩn bị danh sách, ghi kết quả cuộc họp và chốt dữ liệu trước khi ký.</p></div></div>'+
 '<section class="card"><div class="toolbar"><label>Đợt xét<select id="round"><option value="ready">Học kỳ I · 2026–2027 — Đã đóng xét</option><option value="open">Đợt bổ sung tháng 12 — Đang nhận hồ sơ</option></select></label></div><div id="round-info"></div></section><section class="card" id="root-list"></section>';
 document.querySelector('#round').value=state.round;document.querySelector('#round').onchange=e=>{state.round=e.target.value;list();};
 document.querySelector('#round-info').innerHTML=state.round==='open'?'<div class="notice warn">Đợt này chưa Đóng xét. Hoàn tất rà soát và Đóng xét trước khi lập bộ xét Hội đồng.</div>':'<div class="summary"><div><strong>3</strong><span>Nhóm đủ căn cứ</span></div><div><strong>1</strong><span>Nhóm loại khỏi tập đủ điều kiện</span></div><div><strong>Đã chốt nguồn</strong><span>22/11/2026 · 08:30, giờ Việt Nam</span></div></div>';
 const box=document.querySelector('#root-list');
 if(state.round==='open'){box.innerHTML='<h2>Chưa có bộ xét</h2><p class="muted">Chỉ tạo sau khi tập đánh giá đã được kiểm tra và Đóng xét.</p>';return;}
 if(!state.created){box.innerHTML='<div class="card-head"><div><h2>Chuẩn bị bộ xét Hội đồng</h2><p class="muted">Lấy toàn bộ nhóm đủ căn cứ. Mỗi đợt có một bộ, các lần sửa giữ thành phiên bản.</p></div><button id="create">Tạo bộ xét</button></div><div class="notice">Hệ thống chọn một diện có mức hưởng cao nhất cho mỗi nhóm. Giữ đúng thời gian được xác minh, không cộng mức hoặc bù thời gian bằng diện thấp hơn.</div>';document.querySelector('#create').onclick=create;return;}
 const v=state.versions.at(-1);box.innerHTML='<div class="card-head"><h2>Bộ xét của đợt</h2></div><div class="table-wrap"><table><thead><tr><th>Bộ quyết định</th><th>Phiên bản</th><th>Trạng thái</th><th></th></tr></thead><tbody><tr><td><strong>'+escape(v.code)+'</strong><small>Học kỳ I · 2026–2027</small></td><td>Bản '+state.versions.length+'</td><td>'+badge(v)+'</td><td><button id="open" class="outline">Xem bộ xét</button></td></tr></tbody></table></div>';document.querySelector('#open').onclick=()=>{state.selected=state.versions.length-1;state.tab='list';state.screen='detail';render();};
}
function badge(v){return '<span class="badge '+(v.locked?'':'pending')+'">'+(v.locked?'Đã chốt dữ liệu':v.meeting?'Đã ghi cuộc họp':'Trước cuộc họp')+'</span>';}
function create(){modal('<h2>Tạo bộ xét Hội đồng</h2><p class="muted">3 nhóm đủ căn cứ sẽ được đưa vào bộ xét. Đây chưa phải quyết định đã ban hành.</p><form id="create-form"><div class="field-grid"><label class="full">Mã bộ quyết định<input name="code" aria-label="Mã bộ quyết định" required maxlength="128" value="MGHP-HKI-2026"><small>Mã để tra cứu nội bộ; số và ngày quyết định có thể ghi sau cuộc họp.</small></label></div><div class="actions"><button type="button" class="secondary" data-close>Quay lại</button><button>Tạo bộ xét</button></div></form>');document.querySelector('#create-form').onsubmit=e=>{e.preventDefault();const code=e.target.elements.code.value.trim();if(!code){toast('Nhập mã bộ quyết định.',true);return;}state.created=true;state.versions=[{code,number:null,date:null,meeting:null,locked:false,createdAt:new Date().toISOString(),reason:'Lập danh sách từ nguồn đã đóng xét'}];state.selected=0;state.screen='detail';state.tab='list';dialog.close();render();toast('Đã tạo bộ xét với 3 nhóm đủ căn cứ.');};}
function detail(){
 const v=state.versions[state.selected],latest=state.selected===state.versions.length-1;
 main.innerHTML='<div class="page-head"><div><button class="link" id="back">← Danh sách bộ xét</button><h1>'+escape(v.code)+'</h1><p class="muted">Học kỳ I · 2026–2027 <span aria-hidden="true"> / </span> Bản '+(state.selected+1)+' '+(!latest?'· Bản lịch sử, chỉ đọc':'')+'</p></div>'+badge(v)+'</div>'+
 '<ol class="steps"><li class="done"><b>1</b>Nguồn đã đóng xét</li><li class="'+(v.meeting?'done':'current')+'"><b>2</b>Ghi cuộc họp</li><li class="'+(v.locked?'done':v.meeting?'current':'')+'"><b>3</b>Chốt dữ liệu</li></ol>'+
 '<section class="card"><div class="card-head"><div><h2>'+(v.locked?'Dữ liệu đã chốt':v.meeting?'Sẵn sàng kiểm tra và chốt':'Danh sách trước cuộc họp')+'</h2><p class="muted">'+(v.locked?'Bảo toàn dữ liệu và lịch sử. Chuẩn bị PDF và ký được thực hiện tại giai đoạn tiếp theo.':v.meeting?'Xem lại danh sách và thông tin cuộc họp trước khi chốt.':'Mang danh sách và căn cứ đến cuộc họp Hội đồng. Ghi kết quả sau khi cuộc họp thực sự diễn ra.')+'</p></div><div class="actions">'+(latest&&!v.locked?(v.meeting?'<button class="outline" id="edit-meeting">Sửa kết quả cuộc họp</button><button id="lock">Chốt dữ liệu</button>':'<button id="meeting">Ghi kết quả cuộc họp</button>'):'')+'</div></div>'+
 (v.locked?'<div class="notice success">Đã chốt bản '+(state.selected+1)+'. Không thể sửa trực tiếp. Chưa ký và chưa công bố quyết định.<br>Chuyên viên MGHP · '+escape(time(v.lockedAt))+' (giờ Việt Nam)</div>':'')+
 '<div class="tabs" role="tablist" aria-label="Thông tin bộ xét"><button role="tab" data-tab="list" aria-selected="'+(state.tab==='list')+'">Danh sách hưởng <span class="subtle">(3)</span></button><button role="tab" data-tab="meeting" aria-selected="'+(state.tab==='meeting')+'">Cuộc họp & văn bản</button><button role="tab" data-tab="history" aria-selected="'+(state.tab==='history')+'">Lịch sử phiên bản</button></div><div id="panel"></div></section><p class="footer-note">Dữ liệu SYNTHETIC · Hiển thị giờ Việt Nam · Prototype không gọi backend.</p>';
 document.querySelector('#back').onclick=()=>{state.screen='list';render();};document.querySelectorAll('[data-tab]').forEach(b=>b.onclick=()=>{state.tab=b.dataset.tab;detail();});
 document.querySelector('#meeting')?.addEventListener('click',meeting);document.querySelector('#edit-meeting')?.addEventListener('click',meeting);document.querySelector('#lock')?.addEventListener('click',lock);
 const panel=document.querySelector('#panel');
 if(state.tab==='list'){panel.innerHTML='<div class="card-head"><div><h3>Mỗi nhóm chỉ nhận một mức cao nhất</h3><p class="muted subtle">Đã loại nhóm chưa đủ căn cứ. Khoảng hưởng lấy đúng nguồn P08 đã xác minh.</p></div><label class="search">Tìm sinh viên<input id="search" type="search" placeholder="MSSV hoặc họ tên"></label></div><div class="table-wrap"><table><thead><tr><th>Sinh viên</th><th>Diện được chọn</th><th>Mức hưởng</th><th>Thời gian được hưởng</th><th></th></tr></thead><tbody id="students"></tbody></table></div>';studentRows('');document.querySelector('#search').oninput=e=>studentRows(e.target.value);}
 else if(state.tab==='meeting'){panel.innerHTML=v.meeting?'<div class="detail-grid"><div><h3>Cuộc họp Hội đồng</h3><dl><dt>Thời gian thực tế · giờ Việt Nam</dt><dd>'+escape(v.meeting.at.replace('T',' · '))+'</dd><dt>Địa điểm</dt><dd>'+escape(v.meeting.place||'Chưa ghi')+'</dd><dt>Kết luận / căn cứ</dt><dd>'+escape(v.meeting.reason)+'</dd></dl></div><div><h3>Thông tin văn bản</h3><dl><dt>Mã biên bản</dt><dd>'+escape(v.meeting.code)+'</dd><dt>Số quyết định</dt><dd>'+escape(v.number||'Chưa ghi')+'</dd><dt>Ngày quyết định</dt><dd>'+escape(v.date||'Chưa ghi')+'</dd></dl></div></div><div class="notice">Chưa có PDF được gắn vào bản này. P10 lưu dữ liệu Hội đồng; PDF soạn ngoài, upload và ký thuộc bước P11.</div>':'<div class="empty"><h3>Chưa ghi kết quả cuộc họp</h3><p>Cuộc họp thực hiện bên ngoài hệ thống. Sau cuộc họp, chuyên viên ghi thời gian thực tế và kết luận tại đây.</p></div>';}
 else{panel.innerHTML='<p class="muted">Mọi phiên bản cùng thuộc một bộ. Xem bản cũ không thay đổi dữ liệu hiện hành.</p>'+state.versions.map((h,i)=>'<div class="version"><span class="dot"></span><div class="grow"><strong>Bản '+(i+1)+(i===state.versions.length-1?' · Hiện hành':'')+'</strong> '+badge(h)+'<p class="subtle muted">'+escape(h.reason)+'<br>Chuyên viên MGHP · '+escape(time(h.createdAt))+' (giờ Việt Nam)</p></div><button class="outline" data-version="'+i+'">Xem bản '+(i+1)+'</button></div>').reverse().join('');document.querySelectorAll('[data-version]').forEach(b=>b.onclick=()=>{state.selected=Number(b.dataset.version);state.tab='list';detail();});}
}
function studentRows(query){const hits=students.filter(s=>(s.code+' '+s.name).toLocaleLowerCase('vi').includes(query.toLocaleLowerCase('vi')));document.querySelector('#students').innerHTML=hits.length?hits.map(s=>'<tr><td><strong>'+escape(s.name)+'</strong><small>'+s.code+' · '+s.className+'</small></td><td data-label="Diện được chọn">'+escape(s.policy)+'</td><td data-label="Mức hưởng"><strong>'+s.rate+'</strong></td><td data-label="Thời gian hưởng">'+s.period+'</td><td data-label="Căn cứ"><button class="link" data-student="'+s.code+'">Xem căn cứ</button></td></tr>').join(''):'<tr><td colspan="5" class="empty">Không có sinh viên phù hợp.</td></tr>';document.querySelectorAll('[data-student]').forEach(b=>b.onclick=()=>basis(b.dataset.student));}
function basis(code){const s=students.find(s=>s.code===code);modal('<h2>Căn cứ lựa chọn</h2><p><strong>'+s.name+'</strong> · '+s.code+'</p><div class="table-wrap"><table class="mini-table"><thead><tr><th>Diện hợp lệ</th><th>Mức</th><th>Khoảng xác minh</th><th>Kết quả</th></tr></thead><tbody>'+s.candidates.map(c=>'<tr class="'+(c[3]?'selected-row':'')+'"><td>'+c[0]+'</td><td>'+c[1]+'</td><td>'+c[2]+'</td><td><span class="badge '+(c[3]?'':'neutral')+'">'+(c[3]?'Được chọn':'Không chọn')+'</span></td></tr>').join('')+'</tbody></table></div><div class="notice">Chọn một M cao nhất. Không cộng mức, không lấy diện thấp hơn lấp thời gian còn lại. Nguồn đã được P08 xác nhận và Đóng xét.</div><div class="actions"><button data-close>Đóng</button></div>');}
function meeting(){const current=state.versions[state.selected],m=current.meeting;modal('<h2>'+(m?'Sửa kết quả cuộc họp':'Ghi kết quả cuộc họp')+'</h2><p class="muted">Tạo bản sau họp mới, giữ nguyên bản trước. Toàn bộ 3 nhóm đủ căn cứ được giữ trong danh sách.</p><form id="meeting-form"><div class="field-grid"><label>Mã biên bản<input name="code" required value="BB-MGHP-HKI-'+(state.versions.length+1)+'"></label><label>Thời gian họp thực tế<input name="at" type="datetime-local" required value="'+escape(m?.at||'')+'"></label><label class="full">Địa điểm<input name="place" maxlength="512" value="'+escape(m?.place||'')+'"></label><label class="full">Kết luận và căn cứ<input name="reason" aria-label="Kết luận và căn cứ" required maxlength="4000" value="'+escape(m?.reason||'')+'"><small>Ghi kết quả cuộc họp thực tế, không phải ngày dự kiến trong lịch trình.</small></label><label>Số quyết định <span class="muted">(nếu có)</span><input name="number" value="'+escape(current.number||'')+'"></label><label>Ngày quyết định <span class="muted">(nếu có)</span><input name="date" type="date" value="'+escape(current.date||'')+'"></label></div><div class="actions"><button type="button" class="secondary" data-close>Quay lại</button><button>Lưu bản sau họp</button></div></form>');
 document.querySelector('#meeting-form').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target);if(!f.get('code').trim()||!f.get('reason').trim()){toast('Nhập mã biên bản và kết luận cuộc họp.',true);return;}if(new Date(f.get('at'))>new Date()){toast('Thời gian họp thực tế không được ở tương lai.',true);return;}const next={...current,number:f.get('number')||null,date:f.get('date')||null,locked:false,createdAt:new Date().toISOString(),meeting:{code:f.get('code'),at:f.get('at'),place:f.get('place'),reason:f.get('reason')},reason:f.get('reason')};state.versions.push(next);state.selected=state.versions.length-1;state.tab='meeting';dialog.close();detail();toast('Đã lưu bản '+state.versions.length+' sau cuộc họp. Bản cũ được giữ nguyên.');};}
function lock(){modal('<h2>Chốt dữ liệu bộ xét?</h2><p>Bản '+(state.selected+1)+' có <strong>3 nhóm hưởng</strong> và đã ghi cuộc họp Hội đồng. Hệ thống sẽ kiểm lại nguồn, khóa bản này và lưu người chốt, thời gian chốt.</p><div class="notice warn">Sau khi chốt không thể sửa trực tiếp. Thao tác này chưa ký hoặc công bố quyết định.</div><div class="actions"><button class="secondary" data-close>Kiểm tra lại</button><button id="confirm-lock">Xác nhận chốt dữ liệu</button></div>');document.querySelector('#confirm-lock').onclick=()=>{state.versions[state.selected].locked=true;state.versions[state.selected].lockedAt=new Date().toISOString();dialog.close();detail();toast('Đã chốt dữ liệu bản '+(state.selected+1)+'.');};}
render();

